#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m;
    cin >> n >> m;

    vector<ll> v(m);
    for (ll &x : v) cin >> x;

    vector<ll> ans(n + 1, 0);
    unordered_set<ll> used;

    for (ll i = 0; i + 1 < m; ++i) {
        ll diff = v[i + 1] - v[i];
        if (diff <= 0 || diff > n) diff += n;

        ans[v[i]] = diff;
        used.insert(diff);
    }

    unordered_set<ll> available;
    for (ll i = 1; i <= n; ++i) {
        if (!used.count(i)) available.insert(i);
    }

    for (ll i = 1; i <= n; ++i) {
        if (ans[i] == 0 && !available.empty()) {
            auto it = available.begin();
            ll value = *it;
            ans[i] = value;
            available.erase(it);
            used.insert(value);
        }
    }

    if (used.size() != static_cast<size_t>(n)) {
        cout << -1 << '\n';
    } else {
        for (ll i = 1; i <= n; ++i) {
            cout << ans[i] << (i == n ? '\n' : ' ');
        }
    }

    return 0;
}

