#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m;
    cin >> n >> m;

    vector<ll> v(m);
    for (ll &x : v) cin >> x;

    vector<ll> ans(n + 1, 0);
    vector<bool> used(n + 1, false);
    bool valid = true;

    for (ll i = 0; i + 1 < m; ++i) {
        if (v[i] < 1 || v[i] > n || v[i + 1] < 1 || v[i + 1] > n) {
            valid = false;
            break;
        }

        ll difference = (v[i + 1] - v[i] + n) % n;
        if (difference == 0) difference = n;

        if (ans[v[i]] != 0) {
            if (ans[v[i]] != difference) valid = false;
        } else {
            if (used[difference]) {
                valid = false;
            } else {
                ans[v[i]] = difference;
                used[difference] = true;
            }
        }
    }

    if (!valid) {
        cout << -1 << '\n';
        return 0;
    }

    vector<ll> missing;
    for (ll value = 1; value <= n; ++value) {
        if (!used[value]) missing.push_back(value);
    }

    size_t index = 0;
    for (ll i = 1; i <= n; ++i) {
        if (ans[i] == 0) ans[i] = missing[index++];
    }

    for (ll i = 1; i <= n; ++i) {
        cout << ans[i] << (i == n ? '\n' : ' ');
    }

    return 0;
}

